schema_path = project / 'drizzle' / 'schema.ts'
schema_path.write_text("""import { int, mysqlEnum, mysqlTable, text, timestamp, varchar } from \"drizzle-orm/mysql-core\";\n\nexport const users = mysqlTable(\"users\", {\n  id: int(\"id\").autoincrement().primaryKey(),\n  openId: varchar(\"openId\", { length: 64 }).notNull().unique(),\n  name: text(\"name\"),\n  email: varchar(\"email\", { length: 320 }),\n  loginMethod: varchar(\"loginMethod\", { length: 64 }),\n  role: mysqlEnum(\"role\", [\"user\", \"admin\"]).default(\"user\").notNull(),\n  createdAt: timestamp(\"createdAt\").defaultNow().notNull(),\n  updatedAt: timestamp(\"updatedAt\").defaultNow().onUpdateNow().notNull(),\n  lastSignedIn: timestamp(\"lastSignedIn\").defaultNow().notNull(),\n});\n\nexport const cmsUsers = mysqlTable(\"cms_users\", {\n  id: int(\"id\").autoincrement().primaryKey(),\n  email: varchar(\"email\", { length: 320 }).notNull().unique(),\n  name: varchar(\"name\", { length: 160 }).notNull(),\n  passwordHash: varchar(\"passwordHash\", { length: 255 }).notNull(),\n  role: mysqlEnum(\"role\", [\"admin\", \"editor\"]).default(\"admin\").notNull(),\n  isActive: int(\"isActive\").default(1).notNull(),\n  createdAt: timestamp(\"createdAt\").defaultNow().notNull(),\n  updatedAt: timestamp(\"updatedAt\").defaultNow().onUpdateNow().notNull(),\n  lastSignedIn: timestamp(\"lastSignedIn\"),\n});\n\nexport const cmsContentItems = mysqlTable(\"cms_content_items\", {\n  id: int(\"id\").autoincrement().primaryKey(),\n  slug: varchar(\"slug\", { length: 190 }).notNull().unique(),\n  title: varchar(\"title\", { length: 220 }).notNull(),\n  contentType: mysqlEnum(\"contentType\", [\"white-paper\", \"newsletter\", \"funding-opportunity\", \"thought-leadership\"]).notNull(),\n  status: mysqlEnum(\"status\", [\"draft\", \"published\"]).default(\"draft\").notNull(),\n  excerpt: text(\"excerpt\"),\n  body: text(\"body\"),\n  coverImageUrl: text(\"coverImageUrl\"),\n  createdByUserId: int(\"createdByUserId\"),\n  updatedByUserId: int(\"updatedByUserId\"),\n  publishedAt: timestamp(\"publishedAt\"),\n  createdAt: timestamp(\"createdAt\").defaultNow().notNull(),\n  updatedAt: timestamp(\"updatedAt\").defaultNow().onUpdateNow().notNull(),\n});\n\nexport type User = typeof users.$inferSelect;\nexport type InsertUser = typeof users.$inferInsert;\nexport type CmsUser = typeof cmsUsers.$inferSelect;\nexport type InsertCmsUser = typeof cmsUsers.$inferInsert;\nexport type CmsContentItem = typeof cmsContentItems.$inferSelect;\nexport type InsertCmsContentItem = typeof cmsContentItems.$inferInsert;\n""", encoding='utf-8')

db_path = project / 'server' / 'db.ts'
db_path.write_text("""import { and, desc, eq } from \"drizzle-orm\";\nimport { drizzle } from \"drizzle-orm/mysql2\";\nimport { CmsContentItem, CmsUser, InsertCmsContentItem, InsertCmsUser, InsertUser, cmsContentItems, cmsUsers, users } from \"../drizzle/schema\";\nimport { ENV } from './_core/env';\n\nlet _db: ReturnType<typeof drizzle> | null = null;\n\nexport async function getDb() {\n  if (!_db && process.env.DATABASE_URL) {\n    try {\n      _db = drizzle(process.env.DATABASE_URL);\n    } catch (error) {\n      console.warn(\"[Database] Failed to connect:\", error);\n      _db = null;\n    }\n  }\n  return _db;\n}\n\nexport async function upsertUser(user: InsertUser): Promise<void> {\n  if (!user.openId) {\n    throw new Error(\"User openId is required for upsert\");\n  }\n\n  const db = await getDb();\n  if (!db) {\n    console.warn(\"[Database] Cannot upsert user: database not available\");\n    return;\n  }\n\n  const values: InsertUser = { openId: user.openId };\n  const updateSet: Record<string, unknown> = {};\n  const textFields = [\"name\", \"email\", \"loginMethod\"] as const;\n\n  for (const field of textFields) {\n    const value = user[field];\n    if (value === undefined) continue;\n    const normalized = value ?? null;\n    values[field] = normalized;\n    updateSet[field] = normalized;\n  }\n\n  if (user.lastSignedIn !== undefined) {\n    values.lastSignedIn = user.lastSignedIn;\n    updateSet.lastSignedIn = user.lastSignedIn;\n  }\n  if (user.role !== undefined) {\n    values.role = user.role;\n    updateSet.role = user.role;\n  } else if (user.openId === ENV.ownerOpenId) {\n    values.role = 'admin';\n    updateSet.role = 'admin';\n  }\n\n  if (!values.lastSignedIn) values.lastSignedIn = new Date();\n  if (Object.keys(updateSet).length === 0) updateSet.lastSignedIn = new Date();\n\n  await db.insert(users).values(values).onDuplicateKeyUpdate({ set: updateSet });\n}\n\nexport async function getUserByOpenId(openId: string) {\n  const db = await getDb();\n  if (!db) return undefined;\n  const result = await db.select().from(users).where(eq(users.openId, openId)).limit(1);\n  return result[0];\n}\n\nexport async function countCmsUsers() {\n  const db = await getDb();\n  if (!db) return 0;\n  const rows = await db.select({ id: cmsUsers.id }).from(cmsUsers);\n  return rows.length;\n}\n\nexport async function createCmsUser(user: InsertCmsUser) {\n  const db = await getDb();\n  if (!db) throw new Error('Database unavailable');\n  await db.insert(cmsUsers).values(user);\n  return getCmsUserByEmail(user.email);\n}\n\nexport async function getCmsUserByEmail(email: string) {\n  const db = await getDb();\n  if (!db) return undefined;\n  const rows = await db.select().from(cmsUsers).where(eq(cmsUsers.email, email)).limit(1);\n  return rows[0] as CmsUser | undefined;\n}\n\nexport async function getCmsUserById(id: number) {\n  const db = await getDb();\n  if (!db) return undefined;\n  const rows = await db.select().from(cmsUsers).where(eq(cmsUsers.id, id)).limit(1);\n  return rows[0] as CmsUser | undefined;\n}\n\nexport async function touchCmsUserSignIn(id: number) {\n  const db = await getDb();\n  if (!db) return;\n  await db.update(cmsUsers).set({ lastSignedIn: new Date() }).where(eq(cmsUsers.id, id));\n}\n\nexport async function listCmsContentItems() {\n  const db = await getDb();\n  if (!db) return [];\n  return db.select().from(cmsContentItems).orderBy(desc(cmsContentItems.updatedAt));\n}\n\nexport async function createCmsContentItem(item: InsertCmsContentItem) {\n  const db = await getDb();\n  if (!db) throw new Error('Database unavailable');\n  await db.insert(cmsContentItems).values(item);\n  const rows = await db.select().from(cmsContentItems).where(eq(cmsContentItems.slug, item.slug)).limit(1);\n  return rows[0] as CmsContentItem | undefined;\n}\n""", encoding='utf-8')

cms_auth_path = project / 'server' / 'cmsAuth.ts'
cms_auth_path.write_text("""import { jwtVerify, SignJWT } from 'jose';\n\nexport const CMS_SESSION_COOKIE = 'cms_admin_session';\nconst THIRTY_DAYS_MS = 1000 * 60 * 60 * 24 * 30;\n\nexport type CmsSessionPayload = {\n  sub: string;\n  email: string;\n  role: 'admin' | 'editor';\n  name: string;\n};\n\nfunction getSecret() {\n  const value = process.env.JWT_SECRET;\n  if (!value) throw new Error('JWT_SECRET is required for CMS auth');\n  return new TextEncoder().encode(value);\n}\n\nexport async function issueCmsSession(payload: CmsSessionPayload) {\n  return new SignJWT({ email: payload.email, role: payload.role, name: payload.name })\n    .setProtectedHeader({ alg: 'HS256' })\n    .setSubject(payload.sub)\n    .setIssuedAt()\n    .setExpirationTime('30d')\n    .sign(getSecret());\n}\n\nexport async function verifyCmsSession(token: string) {\n  const verified = await jwtVerify(token, getSecret());\n  return verified.payload as unknown as CmsSessionPayload & { sub: string };\n}\n\nexport function getCmsSessionMaxAge() {\n  return THIRTY_DAYS_MS;\n}\n""", encoding='utf-8')

cms_routes_path = project / 'server' / 'cmsRoutes.ts'
cms_routes_path.write_text("""import bcrypt from 'bcryptjs';\nimport { parse as parseCookieHeader } from 'cookie';\nimport type { Express, Request, Response } from 'express';\nimport { createCmsContentItem, createCmsUser, countCmsUsers, getCmsUserByEmail, getCmsUserById, listCmsContentItems, touchCmsUserSignIn } from './db';\nimport { getSessionCookieOptions } from './_core/cookies';\nimport { CMS_SESSION_COOKIE, getCmsSessionMaxAge, issueCmsSession, verifyCmsSession } from './cmsAuth';\n\nasync function getCmsUserFromRequest(req: Request) {\n  const cookies = parseCookieHeader(req.headers.cookie || '');\n  const token = cookies[CMS_SESSION_COOKIE];\n  if (!token) return null;\n  try {\n    const payload = await verifyCmsSession(token);\n    const userId = Number(payload.sub);\n    if (!Number.isFinite(userId)) return null;\n    const user = await getCmsUserById(userId);\n    if (!user || !user.isActive) return null;\n    return user;\n  } catch {\n    return null;\n  }\n}\n\nfunction sanitizeUser(user: NonNullable<Awaited<ReturnType<typeof getCmsUserFromRequest>>> | Awaited<ReturnType<typeof getCmsUserByEmail>>) {\n  if (!user) return null;\n  return {\n    id: user.id,\n    email: user.email,\n    name: user.name,\n    role: user.role,\n    lastSignedIn: user.lastSignedIn,\n  };\n}\n\nexport function registerCmsRoutes(app: Express) {\n  app.get('/api/cms/bootstrap-status', async (_req: Request, res: Response) => {\n    const count = await countCmsUsers();\n    res.json({ requiresBootstrap: count === 0 });\n  });\n\n  app.post('/api/cms/bootstrap', async (req: Request, res: Response) => {\n    const count = await countCmsUsers();\n    if (count > 0) {\n      res.status(409).json({ error: 'CMS admin account already exists' });\n      return;\n    }\n\n    const { email, password, name } = req.body ?? {};\n    if (!email || !password || !name) {\n      res.status(400).json({ error: 'name, email, and password are required' });\n      return;\n    }\n    if (String(password).length < 10) {\n      res.status(400).json({ error: 'Password must be at least 10 characters long' });\n      return;\n    }\n\n    const passwordHash = await bcrypt.hash(String(password), 12);\n    const user = await createCmsUser({\n      email: String(email).trim().toLowerCase(),\n      name: String(name).trim(),\n      passwordHash,\n      role: 'admin',\n      isActive: 1,\n    });\n\n    if (!user) {\n      res.status(500).json({ error: 'Failed to create CMS admin user' });\n      return;\n    }\n\n    const token = await issueCmsSession({\n      sub: String(user.id),\n      email: user.email,\n      role: user.role,\n      name: user.name,\n    });\n    const cookieOptions = getSessionCookieOptions(req);\n    res.cookie(CMS_SESSION_COOKIE, token, { ...cookieOptions, maxAge: getCmsSessionMaxAge() });\n    res.json({ user: sanitizeUser(user) });\n  });\n\n  app.post('/api/cms/login', async (req: Request, res: Response) => {\n    const { email, password } = req.body ?? {};\n    if (!email || !password) {\n      res.status(400).json({ error: 'email and password are required' });\n      return;\n    }\n\n    const user = await getCmsUserByEmail(String(email).trim().toLowerCase());\n    if (!user || !user.isActive) {\n      res.status(401).json({ error: 'Invalid credentials' });\n      return;\n    }\n\n    const valid = await bcrypt.compare(String(password), user.passwordHash);\n    if (!valid) {\n      res.status(401).json({ error: 'Invalid credentials' });\n      return;\n    }\n\n    await touchCmsUserSignIn(user.id);\n    const token = await issueCmsSession({\n      sub: String(user.id),\n      email: user.email,\n      role: user.role,\n      name: user.name,\n    });\n    const cookieOptions = getSessionCookieOptions(req);\n    res.cookie(CMS_SESSION_COOKIE, token, { ...cookieOptions, maxAge: getCmsSessionMaxAge() });\n    res.json({ user: sanitizeUser(user) });\n  });\n\n  app.post('/api/cms/logout', async (req: Request, res: Response) => {\n    const cookieOptions = getSessionCookieOptions(req);\n    res.clearCookie(CMS_SESSION_COOKIE, { ...cookieOptions, maxAge: -1 });\n    res.json({ success: true });\n  });\n\n  app.get('/api/cms/me', async (req: Request, res: Response) => {\n    const user = await getCmsUserFromRequest(req);\n    if (!user) {\n      res.status(401).json({ error: 'Not authenticated' });\n      return;\n    }\n    res.json({ user: sanitizeUser(user) });\n  });\n\n  app.get('/api/cms/content', async (req: Request, res: Response) => {\n    const user = await getCmsUserFromRequest(req);\n    if (!user) {\n      res.status(401).json({ error: 'Not authenticated' });\n      return;\n    }\n    const items = await listCmsContentItems();\n    res.json({ items });\n  });\n\n  app.post('/api/cms/content', async (req: Request, res: Response) => {\n    const user = await getCmsUserFromRequest(req);\n    if (!user) {\n      res.status(401).json({ error: 'Not authenticated' });\n      return;\n    }\n\n    const { title, slug, contentType, excerpt, body, status } = req.body ?? {};\n    if (!title || !slug || !contentType) {\n      res.status(400).json({ error: 'title, slug, and contentType are required' });\n      return;\n    }\n\n    const item = await createCmsContentItem({\n      title: String(title).trim(),\n      slug: String(slug).trim().toLowerCase(),\n      contentType,\n      excerpt: excerpt ? String(excerpt) : null,\n      body: body ? String(body) : null,\n      status: status === 'published' ? 'published' : 'draft',\n      createdByUserId: user.id,\n      updatedByUserId: user.id,\n      publishedAt: status === 'published' ? new Date() : null,\n    });\n\n    res.json({ item });\n  });\n}\n""", encoding='utf-8')

